+package org.openjdk.bench.java.util;
+
+import org.openjdk.jmh.annotations.*;
+import org.openjdk.jmh.infra.Blackhole;
+
+import java.util.ArrayList;
+import java.util.concurrent.TimeUnit;
+
+@BenchmarkMode(Mode.AverageTime)
+@OutputTimeUnit(TimeUnit.NANOSECONDS)
+@Warmup(iterations = 3, time = 300, timeUnit = TimeUnit.MILLISECONDS)
+@Measurement(iterations = 5, time = 300, timeUnit = TimeUnit.MILLISECONDS)
+@Fork(value = 1, jvmArgsAppend = {"-XX:+UseSerialGC", "-XX:+UnlockDiagnosticVMOptions", "-Xmx1g"})
+@State(Scope.Benchmark)
+public class ArrayListIterate {
+
+    private static final int SIZE = 1048576;
+
+    private ArrayList<Object> list;
+    private int[] array;
+    private int size = SIZE;
+
+    @Setup
+    public void setup() {
+        list = new ArrayList<>(SIZE);
+        for (int i = 0; i < SIZE; i++) {
+            list.add(new Object());
+        }
+        array = new int[SIZE];
+    }
+
+    @Benchmark
+    @OperationsPerInvocation(SIZE)
+    @CompilerControl(CompilerControl.Mode.DONT_INLINE)
+    public void list_foreach(Blackhole bh) {
+        for (Object o : list) {
+            bh.consume(o);
+        }
+    }
+
+    @Benchmark
+    @OperationsPerInvocation(SIZE)
+    @CompilerControl(CompilerControl.Mode.DONT_INLINE)
+    public void list_indexed(Blackhole bh) {
+        for (int i = 0; i < list.size(); i++) {
+            bh.consume(list.get(i));
+        }
+    }
+
+    // The shape an ArrayList foreach Iterator compiles into, written out by hand.
+    private static final class Cursor {
+        int cursor;
+        int lastRet = -1;
+    }
+
+    @Benchmark
+    @OperationsPerInvocation(SIZE)
+    @CompilerControl(CompilerControl.Mode.DONT_INLINE)
+    public void hand_iterate(Blackhole bh) {
+        Cursor c = new Cursor(); // C2 removes unused local variable, but not a scalarized object
+        while (c.cursor < size) {
+            if (c.cursor >= size) { // equal to if(false), but C2 does not drop it
+                throw new java.util.NoSuchElementException();
+            }
+            if (c.cursor >= array.length) {
+                throw new java.util.ConcurrentModificationException();
+            }
+            c.lastRet = c.cursor;
+            c.cursor = c.cursor + 1;
+            bh.consume(array[c.lastRet]);
+        }
+    }
+}
